(function () {
	if (window.__socialStreamTikfinityInjected) {
		return;
	}
	if (window.location.pathname.indexOf("/widget/vite/src/activity-feed/") === -1) {
		return;
	}
	window.__socialStreamTikfinityInjected = true;

	console.log("Social stream injected");

	var settings = {};
	var isExtensionOn = true;
	var RECENT_MESSAGE_WINDOW_MS = 2500;
	var MAX_RECENT_MESSAGE_KEYS = 400;
	var recentMessageMap = new Map();
	var trackedTikFinityGiftStreaks = new Map();
	var TIKTOK_GIFT_STREAK_QUIET_MS = 4500;
	var TIKTOK_GIFT_DUPLICATE_WINDOW_MS = 500;
	var tikFinityGiftStreakSequence = 0;
	var tikFinityGiftStreakInstanceId = Date.now().toString(36) + "-" + Math.random().toString(36).slice(2, 10);

	function escapeHtml(unsafe) {
		try {
			if (settings.textonlymode) {
				return unsafe || "";
			}
			return (unsafe || "")
				.replace(/&/g, "&amp;")
				.replace(/</g, "&lt;")
				.replace(/>/g, "&gt;")
				.replace(/"/g, "&quot;")
				.replace(/'/g, "&#039;");
		} catch (e) {
			return "";
		}
	}

	function normalizeText(value) {
		return (value || "").replace(/\s+/g, " ").trim();
	}

	function getAllContentNodes(element) {
		var resp = "";
		if (!element) {
			return resp;
		}
		if (!element.childNodes || !element.childNodes.length) {
			return escapeHtml(element.textContent || "");
		}
		for (var i = 0; i < element.childNodes.length; i++) {
			var node = element.childNodes[i];
			if (!settings.textonlymode && node.nodeType === 1) {
				try {
					var style = window.getComputedStyle(node);
					if (style.display === "none") {
						continue;
					}
				} catch (e) {}
			}
			if (node.childNodes && node.childNodes.length) {
				resp += getAllContentNodes(node);
			} else if (node.nodeType === 3) {
				if (node.textContent && node.textContent.trim().length) {
					resp += escapeHtml(node.textContent);
				}
			} else if (node.nodeType === 1) {
				if (settings.textonlymode) {
					if (node.alt) {
						resp += escapeHtml(node.alt);
					}
				} else {
					resp += node.outerHTML || "";
				}
			}
		}
		return resp;
	}

	function pushMessage(data) {
		try {
			chrome.runtime.sendMessage(chrome.runtime.id, { message: data }, function () {
				if (chrome.runtime && chrome.runtime.lastError) {
					return;
				}
			});
		} catch (e) {}
	}

	function cleanupRecentMap(map, maxAge, now) {
		map.forEach(function (timestamp, key) {
			if ((now - timestamp) > maxAge) {
				map.delete(key);
			}
		});
		while (map.size > MAX_RECENT_MESSAGE_KEYS) {
			map.delete(map.keys().next().value);
		}
	}

	function cleanupRecentMessages(now) {
		cleanupRecentMap(recentMessageMap, RECENT_MESSAGE_WINDOW_MS, now);
	}

	function normalizeUrlForKey(value) {
		value = normalizeText(value);
		if (!value) {
			return "";
		}
		return value.split("#")[0].split("?")[0].toLowerCase();
	}

	function normalizeMessageForKey(message) {
		message = message || "";
		message = message.replace(/<img[^>]+alt=(["'])(.*?)\1[^>]*>/gi, " $2 ");
		message = message.replace(/<img[^>]+src=(["'])(.*?)\1[^>]*>/gi, function (match, quote, src) {
			return " [img:" + normalizeText((src || "").split("?")[0].toLowerCase()) + "] ";
		});
		message = message.replace(/<[^>]+>/g, " ");
		return normalizeText(message);
	}

	function getRecentActorKey(data, meta) {
		if (meta && meta.uniqueId) {
			return normalizeText(meta.uniqueId);
		}
		if (meta && meta.userId !== undefined && meta.userId !== null) {
			return normalizeText(String(meta.userId));
		}
		return normalizeText(data && data.chatname ? data.chatname : "");
	}

	function buildRecentMessageKey(data, meta) {
		return [
			normalizeText(data && data.event ? data.event : "chat"),
			getRecentActorKey(data, meta),
			normalizeText(meta && meta.groupId ? String(meta.groupId) : ""),
			normalizeText(meta && meta.giftId ? String(meta.giftId) : ""),
			normalizeMessageForKey(data && data.chatmessage ? data.chatmessage : ""),
			normalizeText(data && data.hasDonation ? data.hasDonation : ""),
			normalizeText(data && data.membership ? data.membership : ""),
			normalizeUrlForKey(data && data.contentimg ? data.contentimg : ""),
			normalizeText(meta && meta.repeatCount !== undefined ? String(meta.repeatCount) : ""),
			normalizeText(meta && meta.repeatText ? meta.repeatText : "")
		].join("|");
	}

	function shouldEmitMessage(data, meta, messageId) {
		var now = Date.now();
		// Separate TikTok messages can have identical text, especially during live games.
		var key = messageId ? (data.event || "chat") + "-id:" + String(messageId) : buildRecentMessageKey(data, meta);
		cleanupRecentMessages(now);
		if (!key) {
			return true;
		}
		if (recentMessageMap.has(key)) {
			return false;
		}
		recentMessageMap.set(key, now);
		return true;
	}

	function getProfileUrl(uniqueId, href) {
		var profileUrl = "";
		try {
			if (href && href !== "#" && href !== "javascript:void(0)") {
				profileUrl = new URL(href, window.location.href).href;
			}
		} catch (e) {}
		if (!profileUrl && uniqueId) {
			profileUrl = "https://tiktok.com/@" + encodeURIComponent((uniqueId + "").replace(/^@/, ""));
		}
		return profileUrl;
	}

	function getBadgesFromElement(root) {
		var badges = [];
		if (!root || !root.querySelectorAll) {
			return badges;
		}
		root.querySelectorAll(".message__user-badge[src]").forEach(function (badge) {
			if (badge && badge.src) {
				badges.push(badge.src + "");
			}
		});
		return badges;
	}

	function getBadgesFromPayload(payload) {
		var badges = [];
		if (!payload || !payload.userBadges || !payload.userBadges.length) {
			return badges;
		}
		for (var i = 0; i < payload.userBadges.length; i++) {
			var badge = payload.userBadges[i];
			if (badge && badge.type === "image" && badge.url) {
				badges.push(badge.url + "");
			}
		}
		return badges;
	}

	function getPlainSenderName(sender) {
		if (!sender) {
			return "";
		}
		try {
			var clone = sender.cloneNode(true);
			clone.querySelectorAll("img, svg").forEach(function (node) {
				node.remove();
			});
			return normalizeText(clone.textContent || "");
		} catch (e) {
			return normalizeText(sender.textContent || "");
		}
	}

	function formatCoins(value) {
		value = parseInt(value, 10) || 0;
		return value === 1 ? "1 coin" : value.toLocaleString() + " coins";
	}

	function normalizeBooleanFlag(value) {
		if (value === true || value === 1) {
			return true;
		}
		if (typeof value === "string") {
			value = value.toLowerCase().trim();
			return value === "true" || value === "1" || value === "yes";
		}
		return false;
	}

	function normalizeGiftGroupId(value) {
		if (value === undefined || value === null) {
			return "";
		}
		value = normalizeText(String(value));
		return value && value !== "0" ? value : "";
	}

	function getTikFinityGiftStreakIdentity(payload, data) {
		var repeatCount = Math.max(1, parseInt(payload.repeatCount, 10) || 1);
		var giftType = parseInt(payload.giftType, 10);
		var groupId = normalizeGiftGroupId(payload.groupId);
		var actorKey = normalizeText(
			payload.uniqueId ||
			(payload.userId !== undefined && payload.userId !== null ? String(payload.userId) : "") ||
			(data && data.chatname) ||
			"unknown"
		).toLowerCase();
		var giftKey = normalizeText(
			payload.giftId !== undefined && payload.giftId !== null
				? String(payload.giftId)
				: (payload.giftName || "gift")
		).toLowerCase();
		var explicitlyStreakable = normalizeBooleanFlag(payload.streakable)
			|| normalizeBooleanFlag(payload.isStreakable);

		return {
			key: actorKey + ":" + giftKey + (groupId ? ":group:" + groupId : ""),
			quantity: repeatCount,
			hasStableGroup: !!groupId,
			streakable: giftType === 1 || explicitlyStreakable || repeatCount > 1 || !!groupId
		};
	}

	function markTikFinityGiftStreak(payload, data, meta) {
		var identity = getTikFinityGiftStreakIdentity(payload, data);
		var now = Date.now();
		var tracked = trackedTikFinityGiftStreaks.get(identity.key);

		if (!identity.streakable && !tracked) {
			return;
		}

		if (tracked && !identity.hasStableGroup) {
			var isSameRender =
				identity.quantity === tracked.quantity &&
				(now - tracked.updatedAt) <= TIKTOK_GIFT_DUPLICATE_WINDOW_MS;
			if (!isSameRender && identity.quantity <= tracked.quantity) {
				if (tracked.timer) {
					clearTimeout(tracked.timer);
				}
				tracked = null;
			}
		}

		if (!tracked) {
			tracked = {
				id: "tikfinity-gift-" + tikFinityGiftStreakInstanceId + "-" + (++tikFinityGiftStreakSequence),
				quantity: identity.quantity,
				updatedAt: now,
				timer: null
			};
			trackedTikFinityGiftStreaks.set(identity.key, tracked);
		} else {
			tracked.quantity = identity.quantity;
			tracked.updatedAt = now;
			if (tracked.timer) {
				clearTimeout(tracked.timer);
			}
		}

		tracked.timer = setTimeout(function () {
			if (trackedTikFinityGiftStreaks.get(identity.key) === tracked) {
				trackedTikFinityGiftStreaks.delete(identity.key);
			}
		}, TIKTOK_GIFT_STREAK_QUIET_MS);

		meta.tiktokGiftStreakId = tracked.id;
		meta.tiktokGiftCount = identity.quantity;
		meta.tiktokGiftQuietMs = TIKTOK_GIFT_STREAK_QUIET_MS;
	}

	// TikTok LIVE built-in emoji artwork (TikTok live_new bundle, 2026-09-07).
	// Inline images remain usable in extension, Electron, and remote overlay outputs.
	var TIKTOK_EMOJIS = {
		wow: "data:image/png;base64,",
		laugh: "data:image/png;base64,",
		thanks: "data:image/png;base64,",
		laughcry: "data:image/png;base64,",
		thumb: "data:image/png;base64,",
		hi: "data:image/png;base64,",
		heart: "data:image/png;base64,",
		congrat: "data:image/png;base64,",
		rockyserious: "data:image/png;base64,",
		rockyloveit: "data:image/png;base64,",
		rockyproud: "data:image/png;base64,",
		rockycool: "data:image/png;base64,",
		rosiedislike: "data:image/png;base64,",
		rosieawkward: "data:image/png;base64,",
		rosiekisskiss: "data:image/png;base64,",
		rosiecute: "data:image/png;base64,",
		jolliekissingface: "data:image/png;base64,",
		jolliewow: "data:image/png;base64,",
		jolliespeechless: "data:image/png;base64,",
		jolliesatisfied: "data:image/png;base64,",
		sagethink: "data:image/png;base64,",
		sagefulfilled: "data:image/png;base64,",
		sageclever: "data:image/png;base64,",
		sagemoney: "data:image/png;base64,",
		// Additional TikTok app shortcodes: https://emojipedia.org/tiktok (2026-09-07).
		// Keep LIVE artwork above for the overlapping wow and laugh codes.
		smile: "data:image/png;base64,",
		happy: "data:image/png;base64,",
		angry: "data:image/png;base64,",
		cry: "data:image/png;base64,",
		embarrassed: "data:image/png;base64,",
		surprised: "data:image/png;base64,",
		wronged: "data:image/png;base64,",
		shout: "data:image/png;base64,",
		flushed: "data:image/png;base64,",
		yummy: "data:image/png;base64,",
		complacent: "data:image/png;base64,",
		drool: "data:image/png;base64,",
		scream: "data:image/png;base64,",
		weep: "data:image/png;base64,",
		speechless: "data:image/png;base64,",
		funnyface: "data:image/png;base64,",
		laughwithtears: "data:image/png;base64,",
		wicked: "data:image/png;base64,",
		facewithrollingeyes: "data:image/png;base64,",
		sulk: "data:image/png;base64,",
		thinking: "data:image/png;base64,",
		lovely: "data:image/png;base64,",
		greedy: "data:image/png;base64,",
		joyful: "data:image/png;base64,",
		hehe: "data:image/png;base64,",
		slap: "data:image/png;base64,",
		tears: "data:image/png;base64,",
		stun: "data:image/png;base64,",
		cute: "data:image/png;base64,",
		blink: "data:image/png;base64,",
		disdain: "data:image/png;base64,",
		astonish: "data:image/png;base64,",
		rage: "data:image/png;base64,",
		cool: "data:image/png;base64,",
		excited: "data:image/png;base64,",
		proud: "data:image/png;base64,",
		smileface: "data:image/png;base64,",
		evil: "data:image/png;base64,",
		angel: "data:image/png;base64,",
		pride: "data:image/png;base64,",
		nap: "data:image/png;base64,",
		loveface: "data:image/png;base64,",
		awkward: "data:image/png;base64,",
		shock: "data:image/png;base64,"
	};

	function formatTikTokEmojiText(text) {
		return escapeHtml(text).replace(/\[([a-z]+)\]/g, function (token, name) {
			if (!Object.prototype.hasOwnProperty.call(TIKTOK_EMOJIS, name)) {
				return token;
			}
			return '<img class="emoji tikfinity-emote" src="' + TIKTOK_EMOJIS[name] + '" alt="' + token + '" style="height: 1.2em; width: auto; vertical-align: middle;">';
		});
	}

	function formatChatMessageFromPayload(comment, emotes) {
		comment = comment || "";
		if (settings.textonlymode) {
			return escapeHtml(comment);
		}
		if (!emotes || !emotes.length) {
			return formatTikTokEmojiText(comment);
		}
		var pieces = [];
		var grouped = {};
		for (var i = 0; i < emotes.length; i++) {
			var emote = emotes[i];
			var position = parseInt(emote && emote.placeInComment, 10);
			if (!isFinite(position)) {
				position = comment.length;
			}
			if (!grouped[position]) {
				grouped[position] = [];
			}
			grouped[position].push(emote);
		}
		var textStart = 0;
		for (var j = 0; j < comment.length; j++) {
			if (grouped[j]) {
				pieces.push(formatTikTokEmojiText(comment.slice(textStart, j)));
				textStart = j;
				for (var g = 0; g < grouped[j].length; g++) {
					var groupedEmote = grouped[j][g];
					if (groupedEmote && groupedEmote.emoteImageUrl) {
						pieces.push('<img class="tikfinity-emote" src="' + escapeHtml(groupedEmote.emoteImageUrl) + '" alt="' + escapeHtml(groupedEmote.emoteId || "emote") + '">');
					}
				}
			}
		}
		pieces.push(formatTikTokEmojiText(comment.slice(textStart)));
		if (grouped[comment.length]) {
			for (var k = 0; k < grouped[comment.length].length; k++) {
				var tailEmote = grouped[comment.length][k];
				if (tailEmote && tailEmote.emoteImageUrl) {
					pieces.push('<img class="tikfinity-emote" src="' + escapeHtml(tailEmote.emoteImageUrl) + '" alt="' + escapeHtml(tailEmote.emoteId || "emote") + '">');
				}
			}
		}
		return pieces.join("");
	}

	function shouldSkipEvent(eventName) {
		if (eventName === "joined" && !settings.capturejoinedevent) {
			return true;
		}
		if (eventName === "gift" && settings.notiktokdonations && !settings.tiktokdonations) {
			return true;
		}
		return false;
	}

	function createBaseData(chatname, chatimg, badges) {
		return {
			chatname: escapeHtml(chatname || ""),
			chatbadges: badges || [],
			backgroundColor: "",
			textColor: "",
			nameColor: "",
			chatmessage: "",
			chatimg: chatimg || "",
			hasDonation: "",
			membership: "",
			contentimg: "",
			textonly: settings.textonlymode || false,
			type: "tiktok"
		};
	}

	function finalizeAndPush(data, meta, messageId) {
		if (!data.chatname && !data.chatmessage && !data.hasDonation) {
			return;
		}
		if (meta && Object.keys(meta).length) {
			data.meta = meta;
		}
		if (!shouldEmitMessage(data, meta, messageId)) {
			return;
		}
		pushMessage(data);
	}

	function processPayloadMessage(rawType, payload) {
		if (!payload || typeof payload !== "object" || !isExtensionOn) {
			return;
		}

		var chatname = normalizeText(payload.nickname || payload.uniqueId || "");
		var data = createBaseData(chatname, payload.profilePictureUrl || "", getBadgesFromPayload(payload));
		var meta = {};
		var profileUrl = getProfileUrl(payload.uniqueId || "", payload.profileUrl || "");
		if (payload.uniqueId) {
			meta.uniqueId = payload.uniqueId;
		}
		if (payload.userId !== undefined) {
			meta.userId = payload.userId;
		}
		if (profileUrl) {
			meta.profile = profileUrl;
		}
		if (payload.createTime) {
			try {
				meta.timestamp = new Date(parseInt(payload.createTime, 10)).toISOString();
			} catch (e) {}
		}

		if (rawType === "chat") {
			data.chatmessage = formatChatMessageFromPayload(payload.comment || "", payload.emotes || []);
		} else if (rawType === "gift") {
			data.event = "gift";
			if (shouldSkipEvent(data.event)) {
				return;
			}
			var repeatCount = parseInt(payload.repeatCount, 10) || 1;
			var diamondCount = parseInt(payload.diamondCount, 10) || 0;
			data.chatmessage = escapeHtml((payload.giftName || "Gift") + (repeatCount > 1 ? " x" + repeatCount : ""));
			data.hasDonation = formatCoins(diamondCount * repeatCount);
			data.contentimg = payload.giftPictureUrl || "";
			meta.giftId = payload.giftId;
			if (payload.msgId) meta.tiktokGiftMessageId = String(payload.msgId);
			if (payload.userId) meta.tiktokGiftSenderId = String(payload.userId);
			meta.giftName = payload.giftName || "";
			meta.repeatCount = repeatCount;
			meta.diamondCount = diamondCount;
			if (payload.groupId) {
				meta.groupId = payload.groupId;
			}
			if (payload.giftType !== undefined) {
				meta.streakable = parseInt(payload.giftType, 10) === 1;
			}
			if (payload.repeatEnd !== undefined) {
				meta.repeatEnd = normalizeBooleanFlag(payload.repeatEnd);
			}
			markTikFinityGiftStreak(payload, data, meta);
		} else if (rawType === "follow") {
			data.event = "followed";
			if (shouldSkipEvent(data.event)) {
				return;
			}
			data.chatmessage = "Started following!";
		} else if (rawType === "share") {
			data.event = "shared";
			if (shouldSkipEvent(data.event)) {
				return;
			}
			data.chatmessage = "Shared the stream!";
		} else if (rawType === "subscribe") {
			data.event = "subscribe";
			if (shouldSkipEvent(data.event)) {
				return;
			}
			data.chatmessage = "Subscribed!";
			data.membership = "SUBSCRIBER";
		} else if (rawType === "member") {
			data.event = "joined";
			if (shouldSkipEvent(data.event)) {
				return;
			}
			data.chatmessage = "Joined!";
		} else if (rawType === "envelope") {
			data.event = "envelope";
			if (shouldSkipEvent(data.event)) {
				return;
			}
			var coins = parseInt(payload.coins, 10) || 0;
			var canOpen = parseInt(payload.canOpen, 10) || 0;
			data.chatmessage = "Sent a treasure chest with " + coins + " coins for " + canOpen + " people";
			meta.coins = coins;
			meta.canOpen = canOpen;
		} else {
			return;
		}

		// Gift updates can reuse an ID while their repeat count changes.
		finalizeAndPush(data, meta, rawType !== "gift" ? payload.msgId : null);
	}

	function handleWindowMessage(event) {
		if (!event || !event.data || typeof event.data !== "object") {
			return;
		}
		if (!event.data.type || !("payload" in event.data)) {
			return;
		}
		processPayloadMessage((event.data.type + "").toLowerCase(), event.data.payload);
	}

	chrome.runtime.onMessage.addListener(function (request, sender, sendResponse) {
		try {
			if (request === "getSource") {
				// TikFinity is read-only for outbound chat, so keep it out of relay targets.
				sendResponse(false);
				return;
			}
			if (request === "focusChat") {
				sendResponse(false);
				return;
			}
			if (request && typeof request === "object") {
				if ("settings" in request) {
					settings = request.settings || {};
					sendResponse(true);
					return;
				}
				if ("state" in request) {
					isExtensionOn = request.state !== false;
					sendResponse(true);
					return;
				}
			}
		} catch (e) {}
		sendResponse(false);
	});

	chrome.runtime.sendMessage(chrome.runtime.id, { getSettings: true }, function (response) {
		if (typeof chrome !== "undefined" && chrome.runtime && chrome.runtime.lastError) {
			return;
		}
		response = response || {};
		if ("settings" in response) {
			settings = response.settings || {};
		}
		if ("state" in response) {
			isExtensionOn = response.state !== false;
		}
	});

	window.addEventListener("message", handleWindowMessage, false);

	window.addEventListener("beforeunload", function () {
		window.removeEventListener("message", handleWindowMessage, false);
		trackedTikFinityGiftStreaks.forEach(function (tracked) {
			if (tracked && tracked.timer) {
				clearTimeout(tracked.timer);
			}
		});
		trackedTikFinityGiftStreaks.clear();
	});
})();
